void loadSpriteMenuItemsPalette(void) {
    if (spriteMenuItems.palette) {
        return;
    }
    const char *error = NULL;
    spriteMenuItems.palette = playdate->graphics->loadBitmapTable("sprites/sprite-menu_items", &error);
    if (error) {
        playdate->system->error("Unable to load bitmap table of sprite MenuItems: %s", error);
    }
}

